■ 1. 새 파일 lib\api\fetch-json.ts (한 벌. 문구의 유일한 집)
기존 lib\api\client-error.ts 의 httpStatusMessage 를 안에서 부르고, 그것을 감싸는 판정층을 더합니다.

  export type FetchJsonResult<T> =
    | { ok: true; data: T }
    | { ok: false; kind: 'offline'|'network'|'auth'|'server'; status: number; message: string };

  export async function fetchJson<T>(input: RequestInfo, init?: RequestInit): Promise<FetchJsonResult<T>> {
    let res: Response;
    try { res = await fetch(input, init); }
    catch {
      const offline = typeof navigator !== 'undefined' && navigator.onLine === false;
      return { ok:false, kind: offline?'offline':'network', status:0,
        message: offline
          ? '네트워크가 끊겼습니다. 연결을 확인한 뒤 다시 시도하십시오. 입력한 값은 그대로 남아 있습니다.'
          : '서버에 닿지 못했습니다. 잠시 후 다시 시도하십시오. 입력한 값은 그대로 남아 있습니다.' };
    }
    // 세션 만료: middleware.ts:23 matcher 가 /api 를 빼지 않아 lib\supabase\middleware.ts:90-96 이
    // /login 으로 307 을 내고 fetch 가 그것을 따라간다. 최종 경로가 정확히 '/login' 일 때만
    // 인증으로 본다(다른 리다이렉트를 인증으로 오인하지 않게).
    if (res.redirected && new URL(res.url).pathname === '/login') {
      return { ok:false, kind:'auth', status:401,
        message:'로그인이 풀렸습니다. 다시 로그인한 뒤 이 화면에서 다시 저장하십시오.' };
    }
    const body = await res.json().catch(() => ({})) as { message?: string } & T;
    if (!res.ok) {
      return { ok:false, kind:(res.status===401||res.status===403)?'auth':'server', status:res.status,
        message: body?.message ?? httpStatusMessage(res.status) };
    }
    return { ok:true, data: body as T };
  }

핵심은 이 함수가 «절대 던지지 않는다» 는 것입니다. 그래서 호출부의 try/finally 가 거짓말을 그만둡니다. 미들웨어 matcher 자체를 고치는 것은 다른 주제(session-expiry-shows-parser-error)의 몫이고, 여기서는 리다이렉트를 «인증» 으로 분류만 합니다. 둘 다 고쳐도 이 분류는 401 갈래로 계속 맞습니다.

