   const KO = /[가-힣]/;
   export function apiErrorMessage(status: number, body: unknown, fallback?: string): string {
     const b = body as { message?: unknown; error?: unknown } | null;
     if (typeof b?.message === 'string' && b.message.trim()) return b.message.trim();
     // error 는 기계 코드다. 한글이 있을 때만 «키를 잘못 고른 사람 문장» 으로 보고 받는다.
     if (typeof b?.error === 'string' && KO.test(b.error)) return b.error.trim();
     return fallback ?? httpStatusMessage(status);
   }

