   export function invalidInput(
     err: { issues: ReadonlyArray<{ code: string; message: string; path: PropertyKey[] }> },
     fallback = '입력값을 확인해 주십시오.',
   ) {
     // custom 이슈는 스키마 작성자가 한국어로 적은 «업무 규칙» 이다. 있으면 그 문장이 답이다.
     const custom = err.issues.find((i) => i.code === 'custom')?.message;
     const fields = new Set(err.issues.map((i) => String(i.path[0] ?? '')));
     const msg = custom ?? (fields.size > 1 ? `${fallback} (확인할 칸 ${fields.size}개)` : fallback);
     return NextResponse.json({ error: 'invalid_input', message: msg, issues: z.flattenError(err as never) }, { status: 400 });
   }
