import type { PostgrestError } from '@supabase/supabase-js';
/** 이 화면이 «그 조회를 위해» 있으면 실패를 빈 결과로 접지 않고 던집니다. (app)/error.tsx 가 받습니다. */
export function orThrow<T>(res: { data: T | null; error: PostgrestError | null }, what: string): T | null {
  if (res.error) throw new Error(`${what} 조회 실패 [${res.error.code ?? '-'}] ${res.error.message}`);
  return res.data;
}

